{
  "requirement_id": "REQ-003",
  "summary": "Implement pagination for the project task list API (GET /api/projects/{pid}/tasks) with limit, offset, and sorting by task id ascending.",
  "acceptance_criteria": [
    "limit defaults to 20 and must be between 1 and 100; offset defaults to 0 and must be greater than or equal to 0; out of range values return 422.",
    "total represents the total number of matching tasks, unaffected by pagination.",
    "Sequential paging from offset=0 with a fixed limit until the end must collect all tasks without duplication or omission.",
    "items must be an empty array when offset is greater than or equal to total."
  ]
}

